def choose_move(observation):
    sx, sy = observation.get("self_position", [0, 0])
    env = observation.get("environment_name", "resource_collection")

    # Defensive access
    def get_in_obs(key, default=None):
        return observation.get(key, default)

    # Helper to compute direction
    def direction_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x is not None:
            if target_x > sx:
                dx = 1
            elif target_x < sx:
                dx = -1
        if target_y is not None:
            if target_y > sy:
                dy = 1
            elif target_y < sy:
                dy = -1
        return dx, dy

    if env == "pursuit_evasion":
        role = get_in_obs("self_role", "pursuer")
        ox, oy = get_in_obs("opponent_position", [sx, sy])
        if role == "pursuer":
            return list(direction_towards(*get_in_obs("opponent_position", [sx, sy])))
        else:
            corners = [
                [0, 0],
                [0, get_in_obs("grid_height", 1) - 1],
                [get_in_obs("grid_width", 1) - 1, 0],
                [get_in_obs("grid_width", 1) - 1, get_in_obs("grid_height", 1) - 1]
            ]
            ox, oy = get_in_obs("opponent_position", [sx, sy])
            target = min(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            return list(direction_towards(*target))

    if env == "territory_control":
        targets = get_in_obs("unclaimed_cells") or get_in_obs("opponent_territory") or []
        if targets:
            best = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return list(direction_towards(*best))
        else:
            return [0, 0]

    resources = get_in_obs("resources") or []
    if resources:
        best = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return list(direction_towards(*best))

    # Default move towards opponent or center
    ox, oy = get_in_obs("opponent_position", [sx, sy])
    return list(direction_towards(ox, oy))

